approved_command_preview:
$ErrorActionPreference = 'Stop'

$repo = [Environment]::GetEnvironmentVariable('DCOIR_REPO_ROOT','Machine')
$downloads = [Environment]::GetEnvironmentVariable('DCOIR_DOWNLOADS_DIR','Machine')

if ([string]::IsNullOrWhiteSpace($repo)) { throw 'DCOIR_REPO_ROOT is unavailable' }
if ([string]::IsNullOrWhiteSpace($downloads)) { throw 'DCOIR_DOWNLOADS_DIR is unavailable' }

$expectedHead = '421fb8dbd5b03d068d3abb20b5865e1ccc82b67b'
$base = '9dc055d81fba2bcd4e840ad1e9c9645bdc6a6a20'
$branch = 'refactor/issue-550-dcoir-runtime-consolidation'
$requestRel = '.github/chatgpt_staging/exec_requests/issue550-pr553-architecture-characterization-002.json'
$requestPath = Join-Path $repo $requestRel

$sharedHeadBefore = (& git -C $repo rev-parse HEAD).Trim()
if ($LASTEXITCODE -ne 0) { throw 'Unable to read the shared harness checkout HEAD' }

$sharedRefLines = @(& git -C $repo symbolic-ref --quiet --short HEAD 2>$null)
if ($LASTEXITCODE -eq 0) { $sharedRefBefore = ($sharedRefLines -join "`n").Trim() } else { $sharedRefBefore = '' }

if (-not (Test-Path -LiteralPath $requestPath)) { throw "Exec request is missing from the shared harness checkout: $requestRel" }

& git -C $repo fetch --no-tags origin "+refs/heads/$branch`:refs/remotes/origin/$branch"
if ($LASTEXITCODE -ne 0) { throw 'Failed to fetch the PR branch' }

$actualHead = (& git -C $repo rev-parse "refs/remotes/origin/$branch").Trim()
if ($LASTEXITCODE -ne 0 -or $actualHead -ne $expectedHead) { throw "PR head drift: expected $expectedHead but observed $actualHead" }

& git -C $repo merge-base --is-ancestor $base $expectedHead
if ($LASTEXITCODE -ne 0) { throw 'Expected PR product base is not an ancestor of the exact PR head' }

& git -C $repo fetch --no-tags origin '+refs/heads/main:refs/remotes/origin/main'
if ($LASTEXITCODE -ne 0) { throw 'Failed to fetch live main' }

$liveMain = (& git -C $repo rev-parse 'refs/remotes/origin/main').Trim()
if ($LASTEXITCODE -ne 0) { throw 'Unable to resolve live main' }

& git -C $repo merge-base --is-ancestor $base $liveMain
if ($LASTEXITCODE -ne 0) { throw "Original product base $base is no longer an ancestor of live main $liveMain" }

$mainDelta = @(& git -C $repo diff --name-only "$base...$liveMain")
if ($LASTEXITCODE -ne 0) { throw 'Unable to inspect live-main movement from the product base' }

$nonStagingMainDelta = @($mainDelta | Where-Object { -not [string]::IsNullOrWhiteSpace($_) -and $_ -notlike '.github/chatgpt_staging/*' })
if ($nonStagingMainDelta.Count -ne 0) { throw "Live main contains product/source movement beyond the characterized base: $($nonStagingMainDelta -join ', ')" }

$secretNames = @('DCOIR_GITHUB_FG_TOKEN','DCOIR_GITHUB_CL_TOKEN','DCOIR_GEMINI_API','DCOIR_OPENAI_API_KEY','DCOIR_OPENAI_PROJECT_ID','OPENAI_API_KEY')
foreach ($name in $secretNames) {
    [Environment]::SetEnvironmentVariable($name, $null, 'Machine')
    [Environment]::SetEnvironmentVariable($name, $null, 'Process')
    Remove-Item "Env:$name" -ErrorAction SilentlyContinue
}

$runnerTemp = $env:RUNNER_TEMP
if ([string]::IsNullOrWhiteSpace($runnerTemp)) { $runnerTemp = [IO.Path]::GetTempPath() }
$worktree = Join-Path $runnerTemp ('dcoir-pr553-characterization-' + [Guid]::NewGuid().ToString('N'))
$worktreeCreated = $false
$capturedError = $null
$cleanupError = $null

try {
    & git -C $repo worktree add --detach $worktree $expectedHead
    if ($LASTEXITCODE -ne 0) { throw 'Failed to create the isolated PR #553 characterization worktree' }
    $worktreeCreated = $true

    Push-Location $worktree
    try {
        $observedWorktreeHead = (& git rev-parse HEAD).Trim()
        if ($LASTEXITCODE -ne 0 -or $observedWorktreeHead -ne $expectedHead) { throw "Isolated worktree head mismatch: expected $expectedHead but observed $observedWorktreeHead" }

        $expectedFiles = @('.github/dcoir_review/ARCHITECTURE.md','.github/dcoir_review/scripts/dcoir_review_architecture_inventory.py','.github/dcoir_review/scripts/dcoir_review_runtime_module_loader_selftest.py','.github/dcoir_review/scripts/dcoir_review_runtime_provenance.py')
        $changedFiles = @(& git diff --name-only "$base...$expectedHead")
        if ($LASTEXITCODE -ne 0) { throw 'Unable to inspect the exact PR file scope' }
        $scopeDelta = @(Compare-Object -ReferenceObject ($expectedFiles | Sort-Object) -DifferenceObject ($changedFiles | Sort-Object))
        if ($scopeDelta.Count -ne 0) { throw "Unexpected PR file scope: $($changedFiles -join ', ')" }

        & python -m py_compile '.github/dcoir_review/scripts/dcoir_review_architecture_inventory.py' '.github/dcoir_review/scripts/dcoir_review_runtime_module_loader_selftest.py' '.github/dcoir_review/scripts/dcoir_review_runtime_provenance.py'
        if ($LASTEXITCODE -ne 0) { throw 'Python compilation failed' }

        & python '.github/dcoir_review/scripts/dcoir_review_runtime_module_loader_selftest.py'
        if ($LASTEXITCODE -ne 0) { throw 'DCOIR runtime module-loader selftest failed' }

        $inventoryPath = Join-Path $downloads 'dcoir-review-architecture-inventory.json'
        & python '.github/dcoir_review/scripts/dcoir_review_architecture_inventory.py' | Out-File -FilePath $inventoryPath -Encoding utf8
        if ($LASTEXITCODE -ne 0) { throw 'DCOIR architecture inventory failed' }
        $inventory = Get-Content $inventoryPath -Raw | ConvertFrom-Json
        if (@($inventory.missing_modules).Count -ne 0) { throw "Architecture inventory has missing modules: $($inventory.missing_modules -join ', ')" }
        if ([int]$inventory.max_numbered_version -ne 58) { throw "Numbered production patch ceiling changed: $($inventory.max_numbered_version)" }

        $provenancePath = Join-Path $downloads 'dcoir-review-runtime-provenance.json'
        & python '.github/dcoir_review/scripts/dcoir_review_runtime_provenance.py' | Out-File -FilePath $provenancePath -Encoding utf8
        if ($LASTEXITCODE -ne 0) { throw 'DCOIR runtime provenance characterization failed' }
        $provenance = Get-Content $provenancePath -Raw | ConvertFrom-Json
        if (@($provenance.production_patch_sequence).Count -lt 1) { throw 'Runtime provenance did not observe the current production patch sequence' }

        & git diff --check "$base...$expectedHead"
        if ($LASTEXITCODE -ne 0) { throw 'git diff --check failed' }
        $worktreeState = @(& git status --porcelain)
        if ($worktreeState.Count -ne 0) { throw "Characterization modified the isolated worktree: $($worktreeState -join '; ')" }
    } finally { Pop-Location }
} catch {
    $capturedError = $_
} finally {
    if ($worktreeCreated) {
        & git -C $repo worktree remove --force $worktree
        if ($LASTEXITCODE -ne 0) { $cleanupError = "Failed to remove isolated worktree: $worktree" }
    }
}

$sharedHeadAfter = (& git -C $repo rev-parse HEAD).Trim()
if ($LASTEXITCODE -ne 0) { throw 'Unable to read the shared harness checkout HEAD after characterization' }
$sharedRefLines = @(& git -C $repo symbolic-ref --quiet --short HEAD 2>$null)
if ($LASTEXITCODE -eq 0) { $sharedRefAfter = ($sharedRefLines -join "`n").Trim() } else { $sharedRefAfter = '' }
if ($sharedHeadAfter -ne $sharedHeadBefore) { throw "Shared harness checkout HEAD changed: before=$sharedHeadBefore after=$sharedHeadAfter" }
if ($sharedRefAfter -ne $sharedRefBefore) { throw "Shared harness checkout ref changed: before=$sharedRefBefore after=$sharedRefAfter" }
if (-not (Test-Path -LiteralPath $requestPath)) { throw 'Shared harness request disappeared during characterization' }
if ($null -ne $cleanupError) { throw $cleanupError }
if ($null -ne $capturedError) { throw $capturedError }

Write-Host "PR #553 exact-head isolated-worktree architecture characterization passed: $expectedHead"
Write-Host "Live main observed: $liveMain"
Write-Host "Inventory artifact: $inventoryPath"
Write-Host "Runtime provenance artifact: $provenancePath"
Write-Host "Shared harness checkout preserved: $sharedHeadAfter"

